export function getStatementsForArea(areaId: string): Statement[] {
  return statements.filter(s => s.areaId === areaId);
}

export function getStrategiesForArea(areaId: string): Strategy[] {
  return strategies.filter(s => s.areaId === areaId);
}

// --- Runtime overrides / additions applied from the public-content endpoint ---
// Stable defaults captured before any mutation so we can re-merge cleanly.
const _defaultAreas: SensoryArea[] = [...sensoryAreas];
const _defaultStatements: Statement[] = [...statements];
const _defaultStrategies: Strategy[] = [...strategies];

export interface SensoryPublishedPatch {
  overrides: Array<{ item_type: string; item_id: string; field: string; value: string | null; hidden: boolean }>;
  additions: Array<{ id: string; item_type: string; parent_id: string; payload: Record<string, any>; hidden: boolean }>;
}

export function applySensoryPublishedContent(patch: SensoryPublishedPatch) {
  const overrideMap = new Map<string, { value: string | null; hidden: boolean }>();
  const hiddenIds = new Set<string>();
  for (const o of patch.overrides) {
    overrideMap.set(`${o.item_type}|${o.item_id}|${o.field}`, { value: o.value, hidden: o.hidden });
    if (o.field === '__hidden__' && o.hidden) hiddenIds.add(`${o.item_type}|${o.item_id}`);
  }
  const ov = (type: string, id: string, field: string, def: string) =>
    overrideMap.get(`${type}|${id}|${field}`)?.value ?? def;

  sensoryAreas = _defaultAreas.map(a => ({ ...a, label: ov('area', a.id, 'label', a.label) }));

  const baseStatements = _defaultStatements
    .filter(s => !hiddenIds.has(`statement|${s.id}`))
    .map(s => ({
      ...s,
      text: ov('statement', s.id, 'text', s.text),
      source: ov('statement', s.id, 'source', s.source ?? '') || undefined,
    }));
  const addedStatements = patch.additions
    .filter(a => a.item_type === 'statement' && !a.hidden)
    .map(a => ({ id: `add-${a.id}`, areaId: a.parent_id, text: a.payload.text ?? '', source: a.payload.source } as Statement));
  statements = [...baseStatements, ...addedStatements];

  const baseStrategies = _defaultStrategies
    .filter(s => !hiddenIds.has(`strategy|${s.id}`))
    .map(s => ({
      ...s,
      text: ov('strategy', s.id, 'text', s.text),
      source: ov('strategy', s.id, 'source', s.source ?? '') || undefined,
    }));
  const addedStrategies = patch.additions
    .filter(a => a.item_type === 'strategy' && !a.hidden)
    .map(a => ({ id: `add-${a.id}`, areaId: a.parent_id, text: a.payload.text ?? '', source: a.payload.source } as Strategy));
  strategies = [...baseStrategies, ...addedStrategies];
}
